solution:
기존 State에 다음 필드를 추가한다.
```cpp
double deckAngle=0;
bool attached=false;
glm::vec3 lightCoordinate{2,4,3};
```
key의 PRESS 구간에 추가한다. 키 전환 시점의 전시대 행렬로 재표현한다.
```cpp
if(key==GLFW_KEY_L) {
    const auto deck=glm::rotate(glm::mat4(1),glm::radians(float(state.deckAngle)),glm::vec3(0,1,0));
    const auto world=state.attached ? deck*glm::vec4(state.lightCoordinate,1)
                                    : glm::vec4(state.lightCoordinate,1);
    state.attached=!state.attached;
    state.lightCoordinate=glm::vec3(state.attached ? glm::inverse(deck)*world : world);
}
```
update에서 pause 확인 뒤 deckAngle+=20*dt를 추가한다. 기존 y/z 광원 제어는 이 시나리오에서는 사용하지 않는다. 렌더에서 기존 중심 물체·옆 구·광원 marker·궤도 draw를 빼고 다음으로 대체한다(바닥 draw는 유지해도 된다). 이 코드는 기존 view/projection/기본 uniform 전송 뒤다.
```cpp
const auto deck=glm::rotate(glm::mat4(1),glm::radians(float(state.deckAngle)),glm::vec3(0,1,0));
const auto light=state.attached ? glm::vec3(deck*glm::vec4(state.lightCoordinate,1)) : state.lightCoordinate;
vector(shader,"lightPosition",light);
for(int i=0;i<3;++i) {
    const float a=float(2*pi*i/3);
    const auto offset=glm::vec3(2*std::cos(a),.5f,2*std::sin(a));
    const auto self=glm::rotate(glm::mat4(1),glm::radians(float(state.objectDegrees)+30*i),glm::vec3(0,1,0));
    auto model=deck*glm::translate(glm::mat4(1),offset)*self*
        glm::scale(glm::mat4(1),glm::vec3(1,.5f,1.4f));
    scalar(shader,"Ks",.2f+.3f*i);
    draw(shader,meshes[std::size_t(i)],model,{.3f+.2f*i,.7f,.9f-.2f*i});
}
draw(shader,meshes[0],glm::scale(glm::translate(glm::mat4(1),light),glm::vec3(.15f)),colors[state.color],true);
```
기존 objectDegrees와 pause 갱신을 재사용한다. p는 작품 자전, Space는 정지다. 프레임 전환은 표시 위치를 보존하지만 이후 궤도는 달라진다. 질량이나 회전 관성은 모델링하지 않았다.

SceneSetup.cpp의 insert 앞에 추가한다.
```cpp
for(int i=0;i<4;++i) {
    graphics::ObjectSetup p;
    p.size={1,.1f,2}; p.position={-1.65f+1.1f*i,2,0}; p.pivot={0,0,-1};
    p.material.color={.3f,.6f,.8f};
    const auto name="awning"+std::to_string(i);
    scene.addObject(name,p);
    graphics::LayerSetup hinge; hinge.pivot={0,0,-1};
    scene.addLayer(name,"fold",hinge);
}
graphics::PointLight lamp; lamp.position={0,.3f,1};
lamp.color={1,.8f,.3f}; lamp.intensity=1;
scene.addLight("awningLamp",lamp,"awning0");
graphics::ObjectSetup marker; marker.size={.1f,.1f,.1f}; marker.material.unlit=true;
marker.material.color=lamp.color; scene.addObject("awningMarker",marker);
```
ExamController State에 `float openAngle=0;`를 추가한다. 클래스에 bool awningHeld_=false를 추가하고 initialize/reset/focus 상실 때 false로 한다. onKey의 PRESS 필터 앞에 `if(key==GLFW_KEY_H) awningHeld_=action!=GLFW_RELEASE;`를 넣는다. update에 추가한다.
```cpp
state_.openAngle=std::clamp(state_.openAngle+(awningHeld_ ? 40.f:-40.f)*dt,0.f,90.f);
for(int i=0;i<4;++i) {
    graphics::LayerSetup hinge; hinge.pivot={0,0,-1};
    hinge.rotationDegrees.x=-std::clamp(state_.openAngle-10.f*i,0.f,60.f);
    scene_.setLayer("awning"+std::to_string(i),"fold",hinge);
}
```
Console::onRender에서 scene_.syncTools 뒤에 표시 위치를 갱신한다.
```cpp
auto& raw=app_.getScene();
const auto frame=raw.worldMatrix(scene_.object("awning0"));
if(!frame) return false;
const auto pos=glm::vec3(*frame*glm::vec4(0,.3f,1,1));
if(!raw.setWorldPlacement(scene_.object("awningMarker"),glm::translate(glm::mat4(1),pos))) return false;
```
표시 물체는 지역 레이어가 없고 unlit이다. 네 판의 마지막 각도는 모두 60도지만 열리기 시작하는 시점은 다르다. 회전법칙을 직접 정한 애니메이션이다.

main.cpp에 Parcel 정의를 State 앞에 추가하고 State에 배열과 선택을 추가한다.
```cpp
struct Parcel { float x; int route=1,latchedRoute=1; bool latched=false; };
// State 안
std::array<Parcel,3> parcels{{{-4},{-2.7f},{-1.4f}}};
int selected=0;
```
key의 PRESS 구간에 넣는다.
```cpp
if(key==GLFW_KEY_J) state.selected=(state.selected+1)%3;
if(key==GLFW_KEY_K) state.parcels[std::size_t(state.selected)].route*=-1;
```
update의 pause 확인 뒤에 넣는다.
```cpp
for(auto& p:state.parcels) {
    p.x+=1.2f*dt;
    if(p.x>=4) { p.x-=8; p.latched=false; }
    if(!p.latched && p.x>=0) { p.latchedRoute=p.route; p.latched=true; }
}
```
렌더 루프의 기존 중심 물체와 옆 구 draw를 다음으로 교체한다. 바닥·광원·uniform은 보존한다.
```cpp
for(int i=0;i<3;++i) {
    const auto& p=state.parcels[std::size_t(i)];
    const int route=p.latched ? p.latchedRoute:p.route;
    const float z=p.x<0 ? 0.f : route*std::min(p.x,2.f)*.5f;
    auto model=glm::scale(glm::translate(glm::mat4(1),glm::vec3(p.x,0,z)),glm::vec3(.6f));
    scalar(shader,"Ks",i==state.selected ? 1.f:0.f);
    draw(shader,meshes[0],model,route>0 ? glm::vec3(.2f,.8f,.4f):glm::vec3(.9f,.3f,.2f));
}
scalar(shader,"Ks",.8f); // 뒤의 다른 물체에 선택 재질을 남기지 않음
```
기본 dt는 .05초 이하로 제한된다. 이 모델은 한 프레임에 여러 회차를 건너뛰는 큰 시간간격을 다루지 않는다. 임의 큰 dt를 허용할 새 조건이라면 경계 사건을 시간 순으로 처리하거나 작은 단계로 나눈다.

SceneSetup.cpp에 rig와 monitor를 루트 객체로 추가한다.
```cpp
graphics::ObjectSetup rig; rig.size={.8f,.4f,1.2f}; rig.position={3,0,0};
scene.addObject("rig",rig);
graphics::ObjectSetup monitor; monitor.size={.8f,.5f,.08f};
monitor.material.unlit=true; monitor.material.color={.2f,.8f,.9f};
scene.addObject("monitor",monitor);
```
ExamController State에 `double rigPhase=0; bool rigMoving=false;`를 추가한다. onKey PRESS 구간에 `if(key==GLFW_KEY_H) state_.rigMoving=!state_.rigMoving;`를 넣는다. 기존 update의 `auto movement=...`부터 카메라 공전 결과 대입까지의 블록을 아래로 교체한다. key의 WASD/r 상태는 이 시나리오에서 쓰지 않는다고 help도 고친다.
```cpp
state_.rigPhase+=state_.rigMoving ? .4*dt:0;
const float a=float(state_.rigPhase);
const glm::vec3 pos{3*std::cos(a),0,3*std::sin(a)};
const glm::vec3 tangent{-std::sin(a),0,std::cos(a)};
const float yaw=std::atan2(tangent.x,tangent.z);
const auto W=glm::translate(glm::mat4(1),pos)*
    glm::rotate(glm::mat4(1),yaw,glm::vec3(0,1,0));
if(!app_.getScene().setWorldPlacement(scene_.object("rig"),W))
    throw std::runtime_error("rig placement");
state_.camera.position=glm::vec3(W*glm::vec4(0,1.2f,-2,1));
state_.camera.target={0,1,0}; state_.camera.up={0,1,0};
```
기존 아래쪽 scene_.setCamera(state_.camera)는 유지한다. rig에 별도 authoring layer나 native motion을 추가하지 않는 조건이다. 모니터는 Console::onRender에서 syncTools 뒤 갱신한다.
```cpp
auto& raw=app_.getScene();
const auto W=raw.worldMatrix(scene_.object("rig"));
if(!W) return false;
const auto p=glm::vec3(*W*glm::vec4(0,1,0,1));
if(!raw.setWorldPlacement(scene_.object("monitor"),glm::translate(glm::mat4(1),p))) return false;
```
모니터가 화면을 항상 카메라로 향하는 billboard라는 조건은 없다. 월드 XY 방향을 유지한다. 카메라만으로 확인하기 힘들면 시험용 고정 시점을 별도 키로 전환하되 두 카메라를 동시에 쓰지 않는다.

State에 `bool grid=false; double simulationSeconds=0;`를 추가한다. key PRESS 구간에서 T를 토글한다. update의 pause 확인 다음에 simulationSeconds+=dt를 추가한다. 렌더의 중심 물체와 옆 구 draw를 다음으로 대체한다.
```cpp
for(int i=0;i<16;++i) {
    const float phase=float(2*pi*i/16);
    const float height=.5f+.4f*std::sin(float(state.simulationSeconds)*2+phase);
    glm::vec3 pos;
    if(state.grid) pos={(i%4-1.5f)*1.5f,height,(i/4-1.5f)*1.5f};
    else pos={3*std::cos(phase),height,3*std::sin(phase)};
    const auto model=glm::translate(glm::mat4(1),pos)*
        glm::rotate(glm::mat4(1),float(state.simulationSeconds)+phase,glm::vec3(0,1,0))*
        glm::scale(glm::mat4(1),glm::vec3(.6f,1.3f,.35f));
    draw(shader,meshes[2],model,{.2f+.6f*i/15,.7f,.9f-.5f*i/15});
}
```
normalMatrix는 기존 draw에서 각 model의 역전치로 계산된다. 같은 GPU 구 메시를 16회 재사용한다. 16개 VBO를 새로 만들지 않는다. 이 예제는 인스턴스 렌더링이 아닌 반복 draw다. 패턴 전환 시 위치가 즉시 달라지는 것이 명시된 동작이다. 보간 전환이 추가 조건이면 old/new 패턴 위치와 transitionProgress를 별도 상태로 둔다.

SceneSetup.cpp에 추가한다. 세 문은 각 지역 +X 방향으로 뻗는다.
```cpp
for(int i=0;i<3;++i) {
    const float a=glm::radians(120.f*i);
    graphics::ObjectSetup door;
    door.size={1.6f,.7f,.15f}; door.pivot={-.8f,0,0};
    door.position={.5f*std::cos(a),1,-.5f*std::sin(a)};
    door.rotationDegrees.y=120.f*i;
    door.material.color={.2f,.6f,.8f};
    const auto name="door"+std::to_string(i);
    scene.addObject(name,door);
    graphics::LayerSetup hinge; hinge.pivot={-.8f,0,0};
    scene.addLayer(name,"open",hinge);
}
graphics::PointLight alarm; alarm.position={0,3,0};
alarm.color={1,.1f,.1f}; alarm.intensity=0; scene.addLight("alarm",alarm);
```
State에 아래를 추가한다. std::array는 기존 헤더에 포함되어 있다.
```cpp
std::array<float,3> doorAngles{};
std::array<bool,3> targetOpen{};
int selected=0;
double elapsed=0;
```
onKey PRESS 구간에 추가한다.
```cpp
if(key==GLFW_KEY_J) state_.selected=(state_.selected+1)%3;
if(key==GLFW_KEY_K) state_.targetOpen[state_.selected]=!state_.targetOpen[state_.selected];
```
update에 추가한다.
```cpp
state_.elapsed+=dt; bool warning=false;
for(int i=0;i<3;++i) {
    auto& angle=state_.doorAngles[i];
    const float goal=state_.targetOpen[i] ? 70.f:0.f;
    angle+=std::clamp(goal-angle,-45.f*dt,45.f*dt);
    warning=warning || angle>1;
    graphics::LayerSetup h; h.pivot={-.8f,0,0}; h.rotationDegrees.z=angle;
    scene_.setLayer("door"+std::to_string(i),"open",h);
}
auto alarm=scene_.light("alarm");
alarm.intensity=warning && std::fmod(state_.elapsed,1.0)<.5 ? 2.f:0.f;
scene_.setLight("alarm",alarm);
```
F2 토글의 `%4`를 `%5`로 바꾼다. 외부 FragmentShader.glsl에서 uStudyView==3 분기 바로 다음, 합성 else 앞에 넣는다.
```glsl
else if (uStudyView == 4) color.rgb = vec3(step(0.5, dot(diffuse, vec3(0.2126,0.7152,0.0722))));
```
이 모드는 재질색을 곱하기 전 diffuse 에너지의 가중합을 판정한다. 감마 보정된 화면색의 물리 휘도를 측정한다고 설명하지 않는다. 경고 표시 물체가 추가 조건이면 unlit 작은 구를 만들고 intensity 상태와 같은 조건으로 tint를 갱신한다. 현재 요구의 경고는 조명의 켜짐이다.
